import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

// ─── Field metadata ────────────────────────────────────────────────────────────
const FIELD_META = {
  shoot_height_cm:        { label: 'Shoot Height',        unit: 'cm',  icon: 'height'   },
  trunk_circumference_cm: { label: 'Trunk Circumference', unit: 'cm',  icon: 'trunk'    },
  shoot_age_months:       { label: 'Shoot Age',           unit: 'mo',  icon: 'calendar' },
  num_leaves:             { label: 'Leaf Count',          unit: '',    icon: 'leaf'      },
  ccgi_score:             { label: 'CCGI Score',          unit: '',    icon: 'score'     },
  leaf_color:             { label: 'Leaf Colour',         unit: '',    icon: 'palette'   },
  bark_texture:           { label: 'Bark Texture',        unit: '',    icon: 'texture'   },
  bark_color:             { label: 'Bark Colour',         unit: '',    icon: 'palette'   },
  straightness:           { label: 'Straightness',        unit: '',    icon: 'straight'  },
};

// ─── Verdict config ────────────────────────────────────────────────────────────
const VERDICT = {
  'Ready': {
    label: 'Ready for Harvest',
    sub:   'Coppice at 6 cm from ground at a 45° angle for best yield.',
    icon:  'check',
    accent: '#22c55e', dim: '#166534',
    bg: 'linear-gradient(135deg,#22c55e14 0%,#22c55e07 100%)',
    border: '#22c55e35',
    ring: '0 0 0 1px #22c55e30,0 8px 32px #22c55e25',
  },
  'Nearly Ready': {
    label: 'Nearly Ready',
    sub:   'Re-assess in 2–4 weeks. Key indicators are improving.',
    icon:  'clock',
    accent: '#f59e0b', dim: '#92400e',
    bg: 'linear-gradient(135deg,#f59e0b14 0%,#f59e0b07 100%)',
    border: '#f59e0b35',
    ring: '0 0 0 1px #f59e0b30,0 8px 32px #f59e0b20',
  },
  'Not Ready': {
    label: 'Not Ready Yet',
    sub:   'The shoot needs more time. Check again in a month.',
    icon:  'xc',
    accent: '#60a5fa', dim: '#1e3a5f',
    bg: 'linear-gradient(135deg,#60a5fa14 0%,#60a5fa07 100%)',
    border: '#60a5fa35',
    ring: '0 0 0 1px #60a5fa30,0 8px 32px #60a5fa20',
  },
};

const CONF_BARS = [
  { key: 'Ready',        color: '#22c55e' },
  { key: 'Nearly Ready', color: '#f59e0b' },
  { key: 'Not Ready',    color: '#60a5fa' },
];

// ─── Icons ─────────────────────────────────────────────────────────────────────
const PATHS = {
  leaf:     <><path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/></>,
  height:   <><path d="M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h3"/><path d="M16 3h3a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-3"/><path d="M12 8v8"/><path d="M9 11l3-3 3 3"/></>,
  trunk:    <><circle cx="12" cy="12" r="4"/><circle cx="12" cy="12" r="9"/></>,
  calendar: <><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></>,
  palette:  <><circle cx="13.5" cy="6.5" r=".5"/><circle cx="17.5" cy="10.5" r=".5"/><circle cx="8.5" cy="7.5" r=".5"/><circle cx="6.5" cy="12.5" r=".5"/><path d="M12 2C6.5 2 2 6.5 2 12s4.5 10 10 10c.926 0 1.648-.746 1.648-1.688 0-.437-.18-.835-.437-1.125-.29-.289-.438-.652-.438-1.125a1.64 1.64 0 0 1 1.668-1.668h1.996c3.051 0 5.555-2.503 5.555-5.554C21.965 6.012 17.461 2 12 2z"/></>,
  texture:  <><path d="M4 6h16M4 10h16M4 14h16M4 18h16"/></>,
  straight: <><path d="M5 12h14"/><path d="M12 5l7 7-7 7"/></>,
  score:    <><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></>,
  mic:      <><path d="M12 2a3 3 0 0 1 3 3v7a3 3 0 0 1-6 0V5a3 3 0 0 1 3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3M9 22h6"/></>,
  search:   <><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></>,
  check:    <><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="M22 4 12 14.01l-3-3"/></>,
  clock:    <><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></>,
  xc:       <><circle cx="12" cy="12" r="10"/><path d="m15 9-6 6M9 9l6 6"/></>,
  info:     <><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></>,
  chart:    <><path d="M3 3v18h18"/><path d="M18 9l-5 5-4-4-3 3"/></>,
  eye:      <><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7z"/><circle cx="12" cy="12" r="3"/></>,
  sparkle:  <><path d="M9.937 15.5A2 2 0 0 0 8.5 14.063l-6.135-1.582a.5.5 0 0 1 0-.962L8.5 9.936A2 2 0 0 0 9.937 8.5l1.582-6.135a.5.5 0 0 1 .963 0L14.063 8.5A2 2 0 0 0 15.5 9.937l6.135 1.581a.5.5 0 0 1 0 .964L15.5 14.063a2 2 0 0 0-1.437 1.437l-1.582 6.135a.5.5 0 0 1-.963 0z"/></>,
  warning:  <><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3z"/><path d="M12 9v4M12 17h.01"/></>,
  plus:     <><path d="M5 12h14M12 5v14"/></>,
};

function Icon({ name, size = 18, style = {} }) {
  if (name === 'stop') return (
    <svg style={{ width: size, height: size, display: 'inline-block', flexShrink: 0, ...style }}
      viewBox="0 0 24 24" fill="currentColor">
      <rect x="6" y="6" width="12" height="12" rx="2"/>
    </svg>
  );
  return (
    <svg style={{ width: size, height: size, display: 'inline-block', flexShrink: 0, ...style }}
      viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
      {PATHS[name] ?? null}
    </svg>
  );
}

// ─── Global CSS ─────────────────────────────────────────────────────────────────
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Serif+Display:ital@0;1&display=swap');

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --bg:#0c1510;--surf:#111a14;--surf2:#162019;--surf3:#1c2820;
  --bd:#1e2e22;--bd2:#263229;--bd3:#2e3d32;
  --text:#e8ede9;--muted:#6b7f70;--dim:#3d5244;
  --accent:#3dd68c;--accent2:#22c55e;--accent3:#16a34a;
  --gray:#9ca3af;
  --r:14px;--r2:10px;--r3:8px;
  --ease:cubic-bezier(.4,0,.2,1);
}

html{scroll-behavior:smooth}
body{font-family:'DM Sans',sans-serif;background:var(--bg);color:var(--text);
  -webkit-font-smoothing:antialiased;min-height:100vh}

::-webkit-scrollbar{width:4px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--bd2);border-radius:4px}

@keyframes fadeUp{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes barGrow{from{width:0%}}
@keyframes recRing{0%{box-shadow:0 0 0 0 rgba(239,68,68,.5)}70%{box-shadow:0 0 0 10px rgba(239,68,68,0)}100%{box-shadow:0 0 0 0 rgba(239,68,68,0)}}
@keyframes shimmer{0%{background-position:-600px 0}100%{background-position:600px 0}}
@keyframes glow{0%,100%{opacity:.6}50%{opacity:1}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.08)}}
@keyframes warnPulse{0%,100%{border-color:#f59e0b35}50%{border-color:#f59e0b70}}

/* ── Root ── */
.ch{min-height:100vh;background:var(--bg)}

/* ── Topbar ── */
.ch-bar{
  position:sticky;top:0;z-index:100;
  background:rgba(12,21,16,.88);backdrop-filter:blur(18px);
  border-bottom:1px solid var(--bd);
  display:flex;align-items:center;gap:10px;
  padding:0 16px;height:56px;
}
.ch-bar-logo{
  width:32px;height:32px;border-radius:9px;flex-shrink:0;
  background:linear-gradient(135deg,#22c55e,#16a34a);
  display:flex;align-items:center;justify-content:center;color:#fff;
  box-shadow:0 2px 10px #22c55e40;
}
.ch-bar-name{
  font-family:'DM Serif Display',serif;font-size:1rem;font-weight:400;flex:1
}
.ch-bar-badge{
  font-size:.58rem;font-weight:600;letter-spacing:.09em;text-transform:uppercase;
  padding:3px 8px;border-radius:20px;
  background:#22c55e14;color:var(--accent);border:1px solid #22c55e28;
}

/* ── Hero ── */
.ch-hero{
  position:relative;overflow:hidden;
  padding:32px 16px 28px;border-bottom:1px solid var(--bd);
}
.ch-hero::before{
  content:'';position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%,#22c55e0e 0%,transparent 70%),
    radial-gradient(ellipse 40% 40% at 85% 110%,#3dd68c09 0%,transparent 60%);
}
.ch-hero-grid{
  position:absolute;inset:0;opacity:.035;pointer-events:none;
  background-image:linear-gradient(var(--accent) 1px,transparent 1px),
    linear-gradient(90deg,var(--accent) 1px,transparent 1px);
  background-size:40px 40px;
}
.ch-hero-in{position:relative;max-width:600px;margin:0 auto;animation:fadeUp .5s ease both}
.ch-eyebrow{
  display:inline-flex;align-items:center;gap:7px;
  font-size:.63rem;font-weight:600;letter-spacing:.1em;text-transform:uppercase;
  color:var(--accent);margin-bottom:12px;
}
.ch-eyebrow-dot{
  width:5px;height:5px;border-radius:50%;background:var(--accent);
  animation:glow 2s ease infinite;
}
.ch-h1{
  font-family:'DM Serif Display',serif;
  font-size:clamp(1.6rem,5vw,2.15rem);line-height:1.15;
  color:var(--text);margin-bottom:10px;font-weight:400;
}
.ch-h1 em{font-style:italic;color:var(--accent)}
.ch-sub{font-size:.81rem;color:var(--muted);line-height:1.65;max-width:430px}

/* ── Body ── */
.ch-body{
  max-width:600px;margin:0 auto;
  padding:20px 14px 64px;
  display:flex;flex-direction:column;gap:13px;
}

/* ── Card ── */
.ch-card{
  background:var(--surf);border:1px solid var(--bd);
  border-radius:var(--r);overflow:hidden;
  animation:fadeUp .4s ease both;
  transition:border-color .2s var(--ease),box-shadow .2s var(--ease);
}
.ch-card:focus-within{border-color:var(--bd2);box-shadow:0 0 0 3px #22c55e0c}
.ch-card-hdr{
  display:flex;align-items:center;gap:10px;padding:14px 16px 0;
}
.ch-card-ico{
  width:30px;height:30px;border-radius:var(--r3);flex-shrink:0;
  background:var(--surf2);border:1px solid var(--bd2);
  display:flex;align-items:center;justify-content:center;color:var(--accent);
}
.ch-card-lbl{
  font-size:.63rem;font-weight:600;letter-spacing:.09em;
  text-transform:uppercase;color:var(--muted);
}
.ch-card-body{padding:12px 16px 16px}

/* ── Textarea ── */
.ch-ta-wrap{position:relative}
.ch-ta{
  width:100%;min-height:112px;
  background:var(--surf2);color:var(--text);
  border:1px solid var(--bd2);border-radius:var(--r2);
  padding:12px 50px 12px 14px;resize:none;outline:none;
  font-family:'DM Sans',sans-serif;font-size:.88rem;line-height:1.65;
  transition:border-color .2s var(--ease),box-shadow .2s var(--ease);
}
.ch-ta::placeholder{color:var(--muted);font-size:.8rem}
.ch-ta:focus{border-color:#22c55e48;box-shadow:0 0 0 3px #22c55e0c}

/* ── Mic ── */
.ch-mic{
  position:absolute;right:10px;bottom:10px;
  width:34px;height:34px;border-radius:50%;border:none;cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:all .2s var(--ease);
}
.ch-mic.idle{background:var(--surf);border:1px solid var(--bd2);color:var(--muted)}
.ch-mic.idle:hover{border-color:var(--accent);color:var(--accent)}
.ch-mic.rec{background:#ef4444;color:#fff;border:1px solid #ef4444;animation:recRing 1.4s infinite}

/* ── Hint ── */
.ch-hint{
  display:flex;align-items:center;gap:5px;
  font-size:.63rem;color:var(--muted);margin-top:7px;
}

/* ── Button ── */
.ch-btn{
  width:100%;padding:13px 16px;margin-top:12px;
  border:none;border-radius:var(--r2);cursor:pointer;
  font-family:'DM Sans',sans-serif;font-size:.9rem;font-weight:600;
  display:flex;align-items:center;justify-content:center;gap:8px;
  position:relative;overflow:hidden;transition:all .2s var(--ease);
}
.ch-btn.on{
  background:linear-gradient(135deg,#22c55e 0%,#16a34a 100%);color:#fff;
  box-shadow:0 4px 20px #22c55e32;
}
.ch-btn.on:hover{transform:translateY(-1px);box-shadow:0 6px 24px #22c55e42}
.ch-btn.on:active{transform:translateY(0)}
.ch-btn.off{background:var(--surf2);color:var(--muted);cursor:not-allowed;border:1px solid var(--bd2)}
.ch-shimmer{
  position:absolute;inset:0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.15),transparent);
  background-size:600px 100%;animation:shimmer 1.6s infinite;
}

/* ── Spinner ── */
.ch-spin{width:16px;height:16px;border-radius:50%;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;animation:spin .7s linear infinite}
.ch-spin-g{width:16px;height:16px;border-radius:50%;border:2px solid var(--bd2);border-top-color:var(--accent);animation:spin .7s linear infinite}

/* ── Loading ── */
.ch-loading{
  display:flex;align-items:center;gap:10px;
  background:var(--surf);border:1px solid var(--bd2);
  border-radius:var(--r);padding:13px 16px;
  font-size:.81rem;color:var(--muted);animation:fadeIn .25s ease;
}

/* ── Error ── */
.ch-err{
  background:#1a0a0a;border:1px solid #3d1515;
  border-radius:var(--r);padding:14px 16px;animation:fadeUp .3s ease;
}
.ch-err-hd{display:flex;align-items:center;gap:7px;font-size:.79rem;font-weight:600;color:#f87171;margin-bottom:6px}
.ch-err-bd{font-size:.77rem;color:#9a6060;line-height:1.55}
.ch-err-tip{font-size:.7rem;color:#6a4040;margin-top:5px}

/* ── Warning banner ── */
.ch-warn{
  background:#1a140a;border:1px solid #f59e0b30;
  border-radius:var(--r);padding:14px 16px;
  animation:fadeUp .35s ease,warnPulse 2.5s ease infinite;
}
.ch-warn-hd{display:flex;align-items:center;gap:8px;font-size:.8rem;font-weight:600;color:#f59e0b;margin-bottom:6px}
.ch-warn-msg{font-size:.77rem;color:#c4913a;line-height:1.6;margin-bottom:10px}
.ch-warn-progress{background:#1e1608;border-radius:6px;height:5px;overflow:hidden;margin-bottom:8px}
.ch-warn-fill{height:100%;background:linear-gradient(90deg,#f59e0b,#d97706);border-radius:6px;transition:width .6s cubic-bezier(.34,1.56,.64,1)}
.ch-warn-sub{font-size:.69rem;color:#8a6030;line-height:1.55}
.ch-warn-missing{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
.ch-warn-tag{
  font-size:.63rem;font-weight:600;padding:3px 8px;border-radius:20px;
  background:#2a1d08;border:1px solid #f59e0b28;color:#c4913a;
  display:flex;align-items:center;gap:4px;
}

/* ── Pills ── */
.ch-pills{display:grid;grid-template-columns:repeat(auto-fill,minmax(128px,1fr));gap:8px}
.ch-pill{
  background:var(--surf2);border:1px solid var(--bd2);border-radius:var(--r2);
  padding:10px 12px;animation:fadeUp .3s ease both;
  transition:border-color .2s var(--ease);
}
.ch-pill:hover{border-color:#22c55e38}
.ch-pill-lbl{
  display:flex;align-items:center;gap:5px;
  font-size:.58rem;font-weight:600;letter-spacing:.07em;
  text-transform:uppercase;color:var(--muted);margin-bottom:4px;
}
.ch-pill-lbl svg{color:var(--accent);opacity:.8}
.ch-pill-val{font-size:.86rem;font-weight:600;color:var(--text)}

/* ── Divider ── */
.ch-div{
  display:flex;align-items:center;gap:10px;
  font-size:.58rem;font-weight:600;letter-spacing:.1em;
  text-transform:uppercase;color:var(--muted);
  animation:fadeUp .35s ease both;
}
.ch-div::before,.ch-div::after{content:'';flex:1;height:1px;background:var(--bd)}

/* ── Verdict ── */
.ch-verdict{
  border-radius:var(--r);padding:20px;
  display:flex;align-items:flex-start;gap:14px;
  border:1px solid transparent;animation:fadeUp .4s ease;
}
.ch-verdict-ico{
  width:48px;height:48px;border-radius:12px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.07);
}
.ch-verdict-label{font-family:'DM Serif Display',serif;font-size:1.22rem;font-weight:400;margin-bottom:5px}
.ch-verdict-sub{font-size:.76rem;line-height:1.55;opacity:.75}

/* ── Confidence bars ── */
.ch-conf-row{display:flex;align-items:center;gap:10px;margin-bottom:11px}
.ch-conf-row:last-child{margin-bottom:0}
.ch-conf-name{width:108px;font-size:.74rem;color:var(--muted);font-weight:500;flex-shrink:0}
.ch-conf-track{flex:1;height:6px;background:var(--surf2);border-radius:6px;overflow:hidden}
.ch-conf-fill{height:100%;border-radius:6px;animation:barGrow .9s cubic-bezier(.34,1.56,.64,1) both}
.ch-conf-pct{width:36px;text-align:right;font-size:.74rem;font-weight:700;font-variant-numeric:tabular-nums}

/* ── Reasons ── */
.ch-reasons{display:flex;flex-direction:column;gap:8px}
.ch-reason{
  display:flex;gap:10px;align-items:flex-start;
  background:var(--surf2);border:1px solid var(--bd2);
  border-radius:var(--r2);padding:11px 13px;
  animation:fadeUp .35s ease both;transition:border-color .2s var(--ease);
}
.ch-reason:hover{border-color:#22c55e30}
.ch-reason-dot{width:6px;height:6px;border-radius:50%;background:var(--accent);flex-shrink:0;margin-top:7px;box-shadow:0 0 6px var(--accent)}
.ch-reason-txt{font-size:.8rem;line-height:1.62;color:#b5c4b9}

/* ── Footer ── */
.ch-footer{
  text-align:center;font-size:.67rem;color:var(--muted);
  margin-top:8px;padding-bottom:10px;line-height:1.6;
  animation:fadeUp .5s ease both;
}

/* ── Responsive ── */
@media(min-width:540px){
  .ch-hero{padding:40px 24px 36px}
  .ch-body{padding:24px 24px 72px}
  .ch-card-hdr{padding:16px 20px 0}
  .ch-card-body{padding:14px 20px 20px}
  .ch-ta{font-size:.9rem;min-height:120px}
  .ch-bar{padding:0 24px}
}
@media(min-width:860px){
  .ch-hero{padding:52px 32px 44px}
  .ch-body{padding:28px 0 80px}
}
@media(max-width:380px){
  .ch-h1{font-size:1.42rem}
  .ch-pills{grid-template-columns:repeat(2,1fr)}
  .ch-bar-badge{display:none}
  .ch-conf-name{width:88px;font-size:.68rem}
}
`;

function useCSS() {
  useEffect(() => {
    const id = 'ch-styles';
    if (!document.getElementById(id)) {
      const el = document.createElement('style');
      el.id = id; el.textContent = CSS;
      document.head.appendChild(el);
    }
  }, []);
}

// ─── Sub-components ────────────────────────────────────────────────────────────

function TopBar() {
  return (
    <div className="ch-bar">
      <div className="ch-bar-logo"><Icon name="leaf" size={16}/></div>
      <div className="ch-bar-name">CinnamonHarvest</div>
      <div className="ch-bar-badge">AI Powered</div>
    </div>
  );
}

function Hero() {
  return (
    <div className="ch-hero">
      <div className="ch-hero-grid"/>
      <div className="ch-hero-in">
        <div className="ch-eyebrow">
          <div className="ch-eyebrow-dot"/>
          Ceylon Cinnamon · CCGI Certified
        </div>
        <h1 className="ch-h1">Harvest <em>Readiness</em><br/>Checker</h1>
        <p className="ch-sub">
          Describe a cinnamon shoot in plain language or speak your measurements.
          Our AI model assesses harvest readiness instantly.
        </p>
      </div>
    </div>
  );
}

function InputCard({ text, setText, loading, recording, onVoice, onAnalyze }) {
  return (
    <div className="ch-card">
      <div className="ch-card-hdr">
        <div className="ch-card-ico"><Icon name="sparkle" size={15}/></div>
        <div className="ch-card-lbl">Shoot Description</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-ta-wrap">
          <textarea
            className="ch-ta"
            value={text}
            onChange={e => setText(e.target.value)}
            onKeyDown={e => { if (e.key==='Enter'&&!e.shiftKey){e.preventDefault();onAnalyze()} }}
            placeholder={
              'Type or speak shoot details, e.g.:\n"Height 155 cm, trunk 4.2 cm, age 20 months,\ndark brown bark, rough and peeling, brownish green leaves, 18 leaves, very straight"'
            }
          />
          <button className={`ch-mic ${recording?'rec':'idle'}`} onClick={onVoice}
            title={recording?'Stop recording':'Speak your measurements'}>
            <Icon name={recording?'stop':'mic'} size={15}/>
          </button>
        </div>
        <div className="ch-hint">
          <Icon name="mic" size={11}/>
          <span>Tap mic to speak · Press Enter to analyse</span>
        </div>
        <button
          className={`ch-btn ${loading||!text.trim()?'off':'on'}`}
          disabled={loading||!text.trim()}
          onClick={onAnalyze}
        >
          {loading && <div className="ch-shimmer"/>}
          {loading
            ? <><div className="ch-spin"/> Analysing shoot…</>
            : <><Icon name="search" size={16}/> Check Harvest Readiness</>}
        </button>
      </div>
    </div>
  );
}

function Loading({ msg }) {
  if (!msg) return null;
  return (
    <div className="ch-loading">
      <div className="ch-spin-g"/>
      <span>{msg}</span>
    </div>
  );
}

function ErrorCard({ error }) {
  if (!error) return null;
  return (
    <div className="ch-err">
      <div className="ch-err-hd"><Icon name="xc" size={15}/>Connection Error</div>
      <div className="ch-err-bd">{error}</div>
      <div className="ch-err-tip">Make sure the Flask backend is running at {API_BASE}</div>
    </div>
  );
}

// ── Confidence Warning Banner ───────────────────────────────────────────────────
function WarningBanner({ warning }) {
  if (!warning || !warning.low_confidence) return null;
  const pct = warning.completeness_pct ?? 0;

  return (
    <div className="ch-warn">
      <div className="ch-warn-hd">
        <Icon name="warning" size={15}/>
        Low Confidence — Partial Data
      </div>
      <div className="ch-warn-msg">{warning.warning_message}</div>

      {/* Completeness bar */}
      <div style={{ display:'flex', alignItems:'center', gap:10, marginBottom:8 }}>
        <div className="ch-warn-progress" style={{ flex:1 }}>
          <div className="ch-warn-fill" style={{ width:`${pct}%` }}/>
        </div>
        <span style={{ fontSize:'.69rem', color:'#c4913a', fontWeight:700, width:32, textAlign:'right' }}>
          {pct}%
        </span>
      </div>

      {/* Missing field tags */}
      {warning.missing_fields?.length > 0 && (
        <>
          <div className="ch-warn-sub">Add these for a more accurate result:</div>
          <div className="ch-warn-missing">
            {warning.missing_fields.map((f, i) => (
              <div className="ch-warn-tag" key={i}>
                <Icon name="plus" size={9}/>{f}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function DetectedFields({ fields }) {
  const entries = Object.entries(fields).filter(([,v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay:'.05s' }}>
      <div className="ch-card-hdr">
        <div className="ch-card-ico"><Icon name="eye" size={15}/></div>
        <div className="ch-card-lbl">Detected Values</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-pills">
          {entries.map(([k, val], i) => {
            const meta = FIELD_META[k] || { label:k, unit:'', icon:'info' };
            return (
              <div className="ch-pill" key={k} style={{ animationDelay:`${i*.04}s` }}>
                <div className="ch-pill-lbl">
                  <Icon name={meta.icon} size={10}/>
                  {meta.label}
                </div>
                <div className="ch-pill-val">
                  {String(val)}{meta.unit ? ` ${meta.unit}` : ''}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ResultSection({ result }) {
  const v = VERDICT[result.prediction] || VERDICT['Not Ready'];
  return (
    <>
      {/* ── Verdict banner ── */}
      <div className="ch-verdict" style={{
        background: v.bg, borderColor: v.border, boxShadow: v.ring
      }}>
        <div className="ch-verdict-ico" style={{ color: v.accent }}>
          <Icon name={v.icon} size={24}/>
        </div>
        <div>
          <div className="ch-verdict-label" style={{ color: v.accent }}>{v.label}</div>
          <div className="ch-verdict-sub"   style={{ color: v.accent }}>{v.sub}</div>
        </div>
      </div>

      {/* ── Warning (if partial data) ── */}
      {result.warning?.low_confidence && (
        <WarningBanner warning={result.warning}/>
      )}

      {/* ── Confidence bars ── */}
      <div className="ch-card" style={{ animationDelay:'.08s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico"><Icon name="chart" size={15}/></div>
          <div className="ch-card-lbl">Confidence Score</div>
        </div>
        <div className="ch-card-body">
          {CONF_BARS.map(({ key, color }) => (
            <div className="ch-conf-row" key={key}>
              <div className="ch-conf-name">{key}</div>
              <div className="ch-conf-track">
                <div className="ch-conf-fill"
                  style={{ width:`${result.confidence?.[key]??0}%`, background:color }}/>
              </div>
              <div className="ch-conf-pct" style={{ color }}>
                {Math.round(result.confidence?.[key]??0)}%
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ── Analysis reasons ── */}
      <div className="ch-card" style={{ animationDelay:'.14s' }}>
        <div className="ch-card-hdr">
          <div className="ch-card-ico"><Icon name="info" size={15}/></div>
          <div className="ch-card-lbl">Analysis Details</div>
        </div>
        <div className="ch-card-body">
          <div className="ch-reasons">
            {result.reasons?.map((r, i) => (
              <div className="ch-reason" key={i} style={{ animationDelay:`${i*.07}s` }}>
                <div className="ch-reason-dot"/>
                <div className="ch-reason-txt">{r}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  useCSS();

  const [text,    setText]   = useState('');
  const [loading, setLoad]   = useState(false);
  const [statusMsg, setMsg]  = useState('');
  const [error,   setError]  = useState('');
  const [fields,  setFields] = useState(null);
  const [result,  setResult] = useState(null);
  const [rec,     setRec]    = useState(false);

  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Please use Chrome or Edge.'); return; }
    if (rec) { recRef.current?.stop(); setRec(false); return; }
    const r = new SR();
    r.lang = 'en-US'; r.interimResults = true; r.continuous = true;
    recRef.current = r;
    const base = text;
    r.onresult = e => {
      let interim='', final=base;
      for (const res of e.results) {
        if (res.isFinal) final += (final?' ':'') + res[0].transcript;
        else interim = res[0].transcript;
      }
      setText(final + (interim?' '+interim:''));
    };
    r.onerror = () => setRec(false);
    r.onend   = () => setRec(false);
    r.start(); setRec(true);
  }, [rec, text]);

  const analyze = useCallback(async () => {
    if (!text.trim() || loading) return;
    setLoad(true); setError(''); setResult(null); setFields(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse failed (${pr.status}): ${await pr.text()}`);
      const parsedFields = (await pr.json()).fields;
      setFields(parsedFields);

      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!rr.ok) throw new Error(`Predict failed (${rr.status}): ${await rr.text()}`);
      setResult(await rr.json());
      setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior:'smooth', block:'start' }), 120);
    } catch(e) {
      setError(e.message); setMsg('');
    } finally {
      setLoad(false);
    }
  }, [text, loading]);

  return (
    <div className="ch">
      <TopBar/>
      <Hero/>
      <div className="ch-body">
        <InputCard
          text={text} setText={setText}
          loading={loading} recording={rec}
          onVoice={toggleVoice} onAnalyze={analyze}
        />

        <Loading msg={loading ? statusMsg : ''}/>
        <ErrorCard error={error}/>

        {fields && <DetectedFields fields={fields}/>}

        <div ref={resultRef}>
          {result && (
            <>
              <div className="ch-div" style={{ animationDelay:'.05s' }}>Result</div>
              <ResultSection result={result}/>
            </>
          )}
        </div>

        <div className="ch-footer">
          Cinnamon Harvest AI · Ceylon Cinnamon Growers Institute data<br/>
          For guidance only — confirm with a field agronomist before harvest.
        </div>
      </div>
    </div>
  );
}
